export const runSimulation = async (userPrompt: string, mode: SimulationMode): Promise<ResearchResult> => {
  const MIN_SIMULATION_TIME = 4000; 

  const getResult = async () => {
    // 1. Check Mode
    if (mode === SimulationMode.LOCAL) {
        console.log("Starting Nano-LLM Local Simulation...");
        return LocalDiffusionEngine.simulate(userPrompt);
    }

    // 2. Check API Key for Cloud
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        console.warn("No API Key found. Falling back to Nano-LLM.");
        return LocalDiffusionEngine.simulate(userPrompt);
    }

    const ai = new GoogleGenAI({ apiKey });
    const prompt = `Science Sim: "${userPrompt}". Generate realistic research paper JSON. Include 4 scientific benchmark metrics (e.g. Fidelity, Confidence) and a fake hex hash.`;

    try {
        const result = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
            systemInstruction: "You are OmniScience. Generate academic paper JSON. Use scientific tone. Include benchmark metrics.", 
            responseMimeType: "application/json",
            responseSchema: responseSchema,
            temperature: 0.3,
        }
        });

        const text = result.text;
        if (!text) throw new Error("Empty Response");
        return JSON.parse(text) as ResearchResult;

    } catch (error) {
        console.warn("Cloud Error/Quota. Fallback to Local Nano-LLM.", error);
        return LocalDiffusionEngine.simulate(userPrompt);
    }
  };

  const [data] = await Promise.all([
    getResult(),
    new Promise(resolve => setTimeout(resolve, MIN_SIMULATION_TIME))
  ]);

  return data;
};

import React, { useEffect, useState, useRef } from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, ResponsiveContainer, Cell } from 'recharts';
import { Activity, Terminal, Cpu, Scan, User, Dna, Zap, ArrowRight, BarChart3, ShieldCheck, FileCheck } from 'lucide-react';
