    setIsDownloading(true);
    const element = document.getElementById('research-paper-content');

    // Use the global html2pdf from the CDN script
    const html2pdf = (window as any).html2pdf;

    if (!html2pdf) {
      console.error("html2pdf library not found");
      alert("PDF library loading... please try again in a moment.");
      setIsDownloading(false);
      return;
    }

    const opt = {
      margin: [10, 10, 10, 10], // top, left, bottom, right
      filename: `omniscience_report_${data.configUsed.topic.split(' ')[0].toLowerCase()}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true, scrollY: 0 },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    try {
      // Small delay to ensure UI updates before heavy processing
      await new Promise(resolve => setTimeout(resolve, 100));
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error("PDF Download failed, falling back to print dialog:", error);
      window.print();
